# Surah Al-Ahzab (chapter 33) — part 1: ayat 1-10 (IDs 3534-3543)
SURAH = 33

ENTRIES = {
3534: (
"اللہ کے نام سے شروع جو رحمان و رحیم ہے — اے نبی اللہ سے ڈرو اور کافروں اور منافقوں کی اطاعت نہ کرو — بے شک اللہ علیم و حکیم ہے",
"""۱۔ نبی ﷺ کو حکم — تقویٰ؛ کافر و منافق کی نافرمانی؛ علیم و حکیم۔
۲۔ ’’بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ يَا أَيُّهَا النَّبِيُّ اتَّقِ اللَّهَ وَلَا تُطِعِ الْكَافِرِينَ وَالْمُنَافِقِينَ إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا‘‘ — اللہ کے نام سے شروع جو رحمان و رحیم ہے — اے نبی اللہ سے ڈرو اور کافروں اور منافقوں کی اطاعت نہ کرو — بے شک اللہ علیم و حکیم ہے — یعنی اللہ کے نام سے شروع جو رحمان و رحیم ہے اے نبی اللہ سے ڈرو اور کافروں اور منافقوں کی اطاعت نہ کرو بے شک اللہ علیم و حکیم ہے۔
۳۔ عملی سبق: تقویٰ اختیار کرو؛ کافروں و منافقوں کی اطاعت نہ کرو؛ اللہ سے ڈرو۔"""
),
3535: (
"اور اس کی پیروی کرو جو تمہارے رب کی طرف سے تم پر وحی کیا جائے — بے شک اللہ تمہارے اعمال سے باخبر ہے",
"""۱۔ نبی ﷺ کو حکم — وحی کی پیروی؛ اللہ کی باخبری۔
۲۔ ’’وَاتَّبِعْ مَا يُوحَىٰ إِلَيْكَ مِن رَّبِّكَ إِنَّ اللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا‘‘ — اور اس کی پیروی کرو جو تمہارے رب کی طرف سے تم پر وحی کیا جائے — بے شک اللہ تمہارے اعمال سے باخبر ہے — یعنی اور اس کی پیروی کرو جو تمہارے رب کی طرف سے تم پر وحی کیا جائے بے شک اللہ تمہارے اعمال سے باخبر ہے۔
۳۔ عملی سبق: وحی اور قرآن کی پیروی کرو؛ اللہ سے ڈرو؛ نیکیاں کماؤ۔"""
),
3536: (
"اور اللہ پر بھروسہ کرو — اور اللہ کافی کارساز ہے",
"""۱۔ توکل — اللہ؛ کافی وکیل۔
۲۔ ’’وَتَوَكَّلْ عَلَى اللَّهِ وَكَفَىٰ بِاللَّهِ وَكِيلًا‘‘ — اور اللہ پر بھروسہ کرو — اور اللہ کافی کارساز ہے — یعنی اور اللہ پر بھروسہ کرو اور اللہ کافی کارساز ہے۔
۳۔ عملی سبق: اللہ پر توکل کرو؛ اس پر بھروسہ رکھو؛ اس سے ڈرو۔"""
),
3537: (
"اللہ نے کسی مرد کے سینے میں دو دل نہیں بنائے — اور نہ تمہاری بیویاں جن سے تم ظِہار کرتے ہو انہیں تمہاری مائیں بنایا — اور نہ تمہارے پالے ہوئے لڑکوں کو تمہارے بیٹے بنایا — یہ تمہارا منہ سے کہنا ہے — اور اللہ حق کہتا ہے اور وہ راہ دکھاتا ہے",
"""۱۔ تین غلط تصورات — دو دل؛ ظِہار کی بیویاں مائیں نہیں؛ دعوۃ بیٹا نہیں۔
۲۔ ’’مَّا جَعَلَ اللَّهُ لِرَجُلٍ مِّن قَلْبَيْنِ فِي جَوْفِهِ وَمَا جَعَلَ أَزْوَاجَكُمُ اللَّائِي تُظَاهِرُونَ مِنْهُنَّ أُمَّهَاتِكُمْ وَمَا جَعَلَ أَدْعِيَاءَكُمْ أَبْنَاءَكُمْ ذَٰلِكُمْ قَوْلُكُم بِأَفْوَاهِكُمْ وَاللَّهُ يَقُولُ الْحَقَّ وَهُوَ يَهْدِي السَّبِيلَ‘‘ — اللہ نے کسی مرد کے سینے میں دو دل نہیں بنائے — اور نہ تمہاری بیویاں جن سے تم ظِہار کرتے ہو انہیں تمہاری مائیں بنایا — اور نہ تمہارے پالے ہوئے لڑکوں کو تمہارے بیٹے بنایا — یہ تمہارا منہ سے کہنا ہے — اور اللہ حق کہتا ہے اور وہ راہ دکھاتا ہے — یعنی اللہ نے کسی مرد کے سینے میں دو دل نہیں بنائے اور نہ تمہاری بیویاں جن سے تم ظِہار کرتے ہو انہیں تمہاری مائیں بنایا اور نہ تمہارے پالے ہوئے لڑکوں کو تمہارے بیٹے بنایا یہ تمہارا منہ سے کہنا ہے اور اللہ حق کہتا ہے اور وہ راہ دکھاتا ہے۔
۳۔ عملی سبق: زبان کی باتوں کو حقیقت نہ سمجھو؛ اللہ کے حق پر عمل کرو؛ اس سے ڈرو۔"""
),
3538: (
"انہیں ان کے باپوں کی طرف منسوب کرو — یہ اللہ کے نزدیک زیادہ انصاف ہے — اگر تم ان کے باپ نہ جانتے ہو تو وہ تمہارے دینی بھائی اور تمہارے دوست ہیں — اور تم پر کوئی حرج نہیں جو تم سے غلطی سے ہو گیا — لیکن اس میں حرج ہے جس کا تمہارے دل ارادہ کرتے ہیں — اور اللہ غفور و رحیم ہے",
"""۱۔ نسبت — باپ سے منسوب کرنا؛ انصاف؛ دینی بھائی؛ غلطی بمقابلہ ارادہ؛ مغفرت۔
۲۔ ’’ادْعُوهُمْ لِآبَائِهِمْ هُوَ أَقْسَطُ عِندَ اللَّهِ فَإِن لَّمْ تَعْلَمُوا آبَاءَهُمْ فَإِخْوَانُكُمْ فِي الدِّينِ وَمَوَالِيكُمْ وَلَيْسَ عَلَيْكُمْ جُنَاحٌ فِيمَا أَخْطَأْتُم بِهِ وَلَٰكِن مَّا تَعَمَّدَتْ قُلُوبُكُمْ وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا‘‘ — انہیں ان کے باپوں کی طرف منسوب کرو — یہ اللہ کے نزدیک زیادہ انصاف ہے — اگر تم ان کے باپ نہ جانتے ہو تو وہ تمہارے دینی بھائی اور تمہارے دوست ہیں — اور تم پر کوئی حرج نہیں جو تم سے غلطی سے ہو گیا — لیکن اس میں حرج ہے جس کا تمہارے دل ارادہ کرتے ہیں — اور اللہ غفور و رحیم ہے — یعنی انہیں ان کے باپوں کی طرف منسوب کرو یہ اللہ کے نزدیک زیادہ انصاف ہے اگر تم ان کے باپ نہ جانتے ہو تو وہ تمہارے دینی بھائی اور تمہارے دوست ہیں اور تم پر کوئی حرج نہیں جو تم سے غلطی سے ہو گیا لیکن اس میں حرج ہے جس کا تمہارے دل ارادہ کرتے ہیں اور اللہ غفور و رحیم ہے۔
۳۔ عملی سبق: انصاف سے نسب کرو؛ غلطیوں پر مغفرت مانگو؛ ارادتاً گناہ سے بچو۔"""
),
3539: (
"نبی مومنوں کے لیے ان کی جانوں پر مقدم ہیں — اور اس کی بیویاں ان کی مائیں ہیں — اور قرابت دار اللہ کی کتاب میں بعض بعض پر اولیٰ ہیں مومنین اور مہاجرین میں سے — سوائے یہ کہ تم اپنے دوستوں سے کوئی معروف سلوک کرنا چاہو — یہ کتاب میں درج ہے",
"""۱۔ نبی ﷺ کی فضیلت — جانوں پر مقدم؛ ازواج مطہرات مائیں؛ قرابتداروں کی اولیت؛ کتاب میں درج۔
۲۔ ’’النَّبِيُّ أَوْلَىٰ بِالْمُؤْمِنِينَ مِنْ أَنفُسِهِمْ وَأَزْوَاجُهُ أُمَّهَاتُهُمْ وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِي كِتَابِ اللَّهِ مِنَ الْمُؤْمِنِينَ وَالْمُهَاجِرِينَ إِلَّا أَن تَفْعَلُوا إِلَىٰ أَوْلِيَائِكُم مَّعْرُوفًا كَانَ ذَٰلِكَ فِي الْكِتَابِ مَسْطُورًا‘‘ — نبی مومنوں کے لیے ان کی جانوں پر مقدم ہیں — اور اس کی بیویاں ان کی مائیں ہیں — اور قرابت دار اللہ کی کتاب میں بعض بعض پر اولیٰ ہیں مومنین اور مہاجرین میں سے — سوائے یہ کہ تم اپنے دوستوں سے کوئی معروف سلوک کرنا چاہو — یہ کتاب میں درج ہے — یعنی نبی مومنوں کے لیے ان کی جانوں پر مقدم ہیں اور اس کی بیویاں ان کی مائیں ہیں اور قرابت دار اللہ کی کتاب میں بعض بعض پر اولیٰ ہیں مومنین اور مہاجرین میں سے سوائے یہ کہ تم اپنے دوستوں سے کوئی معروف سلوک کرنا چاہو یہ کتاب میں درج ہے۔
۳۔ عملی سبق: نبی ﷺ کی محبت کو اپنی جان سے زیادہ رکھو؛ ازواجِ مطہرات کا احترام کرو۔"""
),
3540: (
"اور جب ہم نے نبیوں سے ان کا عہد لیا — اور آپ سے اور نوحؑ، ابراہیمؑ، موسیٰؑ اور عیسیٰؑ ابنِ مریم سے — اور ہم نے ان سے پختہ عہد لیا",
"""۱۔ پیغمبروں کا عہد — نبی ﷺ؛ نوحؑ؛ ابراہیمؑ؛ موسیٰؑ؛ عیسیٰؑ؛ پختہ میثاق۔
۲۔ ’’وَإِذْ أَخَذْنَا مِنَ النَّبِيِّينَ مِيثَاقَهُمْ وَمِنكَ وَمِن نُّوحٍ وَإِبْرَاهِيمَ وَمُوسَىٰ وَعِيسَى ابْنِ مَرْيَمَ وَأَخَذْنَا مِنْهُم مِّيثَاقًا غَلِيظًا‘‘ — اور جب ہم نے نبیوں سے ان کا عہد لیا — اور آپ سے اور نوحؑ، ابراہیمؑ، موسیٰؑ اور عیسیٰؑ ابنِ مریم سے — اور ہم نے ان سے پختہ عہد لیا — یعنی اور جب ہم نے نبیوں سے ان کا عہد لیا اور آپ سے اور نوحؑ ابراہیمؑ موسیٰؑ اور عیسیٰؑ ابنِ مریم سے اور ہم نے ان سے پختہ عہد لیا۔
۳۔ عملی سبق: اپنے عہد پر قائم رہو؛ نبی ﷺ کی اطاعت کرو؛ اللہ سے ڈرو۔"""
),
3541: (
"تاکہ سچے لوگوں سے ان کے سچ کے بارے میں سوال ہو — اور اس نے کافروں کے لیے دردناک عذاب تیار کیا ہے",
"""۱۔ قیامت — سچوں سے سوال؛ کافروں کا دردناک عذاب۔
۲۔ ’’لِّيَسْأَلَ الصَّادِقِينَ عَن صِدْقِهِمْ وَأَعَدَّ لِلْكَافِرِينَ عَذَابًا أَلِيمًا‘‘ — تاکہ سچے لوگوں سے ان کے سچ کے بارے میں سوال ہو — اور اس نے کافروں کے لیے دردناک عذاب تیار کیا ہے — یعنی تاکہ سچے لوگوں سے ان کے سچ کے بارے میں سوال ہو اور اس نے کافروں کے لیے دردناک عذاب تیار کیا ہے۔
۳۔ عملی سبق: سچے بنو؛ کفر سے بچو؛ قیامت کی تیاری کرو۔"""
),
3542: (
"اے ایمان والو اللہ کی نعمت اپنے اوپر یاد کرو جب تم پر لشکر آئے تھے — تو ہم نے ان پر ہوا اور وہ لشکر بھیجے جو تم نے نہیں دیکھے — اور اللہ تمہارے اعمال دیکھ رہا ہے",
"""۱۔ غزوۂ احزاب — لشکروں کی آمد؛ ہوا و فرشتے؛ اللہ کی بصیرت۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَۃَ اللَّهِ عَلَيْكُمْ إِذْ جَاءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا وَكَانَ اللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا‘‘ — اے ایمان والو اللہ کی نعمت اپنے اوپر یاد کرو جب تم پر لشکر آئے تھے — تو ہم نے ان پر ہوا اور وہ لشکر بھیجے جو تم نے نہیں دیکھے — اور اللہ تمہارے اعمال دیکھ رہا ہے — یعنی اے ایمان والو اللہ کی نعمت اپنے اوپر یاد کرو جب تم پر لشکر آئے تھے تو ہم نے ان پر ہوا اور وہ لشکر بھیجے جو تم نے نہیں دیکھے اور اللہ تمہارے اعمال دیکھ رہا ہے۔
۳۔ عملی سبق: اللہ کی نعمتیں یاد کرو؛ اس کی مدد پر بھروسہ رکھو؛ اس سے ڈرو۔"""
),
3543: (
"جب وہ تمہارے اوپر سے اور تمہارے نیچے سے آئے — اور جب نگاہیں بھٹک گئیں اور دل حلق تک پہنچ گئے — اور تم اللہ کے بارے میں مختلف قسم کے گمان کرنے لگے",
"""۱۔ غزوۂ احزاب — چہار جانب دشمن؛ شدید خوف؛ مختلف گمان۔
۲۔ ’’إِذْ جَاءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ الْأَبْصَارُ وَبَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ وَتَظُنُّونَ بِاللَّهِ الظُّنُونَا‘‘ — جب وہ تمہارے اوپر سے اور تمہارے نیچے سے آئے — اور جب نگاہیں بھٹک گئیں اور دل حلق تک پہنچ گئے — اور تم اللہ کے بارے میں مختلف قسم کے گمان کرنے لگے — یعنی جب وہ تمہارے اوپر سے اور تمہارے نیچے سے آئے اور جب نگاہیں بھٹک گئیں اور دل حلق تک پہنچ گئے اور تم اللہ کے بارے میں مختلف قسم کے گمان کرنے لگے۔
۳۔ عملی سبق: آزمائش میں اللہ پر بھروسہ رکھو؛ اچھے گمان رکھو؛ اس سے ڈرو۔"""
),
}
